AC::YieldIfEvent(){	short eventMask = mDownMask + keyDownMask + autoKeyMask;	EventRecord event;	bool yielded = ::EventAvail(eventMask, &event);	if (yielded)	{		ThrowIfOSErr_AC(YieldToThread(kApplicationThreadID));		fNextYieldTime = (unsigned long)::TickCount() + fNumTicks;	}	return yielded;}//----------------------------------------------------------------------------------------// CThreadYielder_AC::YieldNow//----------------------------------------------------------------------------------------void CThreadYielder_AC::YieldNow(){	fNextYieldTime = (unsigned long)::TickCount() + fNumTicks;	ThrowIfOSErr_AC(YieldToAnyThread());}//----------------------------------------------------------------------------------------// End of CThreadYielder_AC.cpp